"""Regression tests for PostgreSQL reverse-DDL type normalization."""
from __future__ import annotations

import pytest

from synapse.adapters.emitters.relational_emitter import RelationalEmitter
from synapse.domain.heuristics.reverse import propose_reverse
from synapse.domain.ir.document import ArrayProfile, Collection, DeclaredConstraints, DocumentIR, FieldKind, FieldNode, IdProfile, MongoIndex, RefCandidate, TypeObservation


@pytest.mark.parametrize(
    "identity_type",
    [
        "BIGINT GENERATED BY DEFAULT AS IDENTITY",
        "BIGINT GENERATED ALWAYS AS IDENTITY",
        "BIGINT GENERATED BY DEFAULT AS IDENTITY (START WITH 1)",
    ],
)
def test_identity_column_reused_as_foreign_key_type_is_plain_bigint(identity_type: str) -> None:
    emitter = RelationalEmitter(dialect="postgresql")
    root = {"columns": [{"name": "id", "sql_type": identity_type}]}

    assert emitter._column_type(root, "id") == "BIGINT"


def test_postgresql_array_table_references_identity_pk_with_plain_bigint() -> None:
    array = FieldNode(
        path="tags", name="tags", kind=FieldKind.ARRAY,
        types=[TypeObservation(bson_type="array", count=5, rate=1.0)],
        sample_size=5, presence_rate=1.0, null_rate=0.0, absent_rate=0.0,
        array=ArrayProfile(element_kind=FieldKind.SCALAR,
                           element_types=[TypeObservation(bson_type="string", count=5, rate=1.0)]),
    )
    status = FieldNode(
        path="status", name="status", kind=FieldKind.SCALAR,
        types=[TypeObservation(bson_type="string", count=5, rate=1.0)],
        sample_size=5, presence_rate=1.0, null_rate=0.0, absent_rate=0.0,
    )
    ir = DocumentIR(collections=[Collection(
        name="order_tags", fields=[array, status],
        id_profile=IdProfile(types=[TypeObservation(bson_type="objectId", count=5, rate=1.0)], sample_size=5),
        indexes=[
            MongoIndex(name="_id_", keys=[("_id", 1)], unique=True),
            MongoIndex(name="_id_status", keys=[("_id", 1), ("status", 1)]),
            MongoIndex(name="uq_order_tags_legacy_pk", keys=[("_legacy.pk", 1)], unique=True),
            MongoIndex(name="tags_1", keys=[("tags", 1)]),
            MongoIndex(name="partial_status", keys=[("status", 1)], partial_filter={"status": "open"}),
            MongoIndex(name="sparse_email", keys=[("status", 1)], unique=True, sparse=True),
        ],
    )])

    artifacts = RelationalEmitter(dialect="postgresql").emit(ir, propose_reverse(ir))

    assert '"id" BIGINT GENERATED BY DEFAULT AS IDENTITY NOT NULL' in artifacts.pre_load_sql
    assert '"order_tags_id" BIGINT NOT NULL' in artifacts.pre_load_sql
    assert '"order_tags_id" BIGINT GENERATED' not in artifacts.pre_load_sql
    assert "GENERATED BY IDENTITY" not in artifacts.pre_load_sql
    assert '"legacy_mongo_id"' not in artifacts.pre_load_sql
    assert '"_id"' not in artifacts.pre_load_sql
    assert 'CREATE INDEX "ix_order_tags_id"' not in artifacts.post_load_sql
    assert 'CREATE INDEX "ix_order_tags_id_status"' not in artifacts.post_load_sql
    assert 'CREATE UNIQUE INDEX "ix_order_tags_legacy_pk"' not in artifacts.post_load_sql
    assert 'CREATE INDEX "ix_order_tags_tags"' not in artifacts.post_load_sql
    assert "partial-filter semantics" in " ".join(item["reason"] for item in artifacts.not_translated)
    assert "sparse unique semantics" in " ".join(item["reason"] for item in artifacts.not_translated)
    assert '"_synapse_reverse_idmap"' in artifacts.pre_load_sql


def test_required_reference_column_is_nullable_for_phase1_then_fk_added_postload() -> None:
    reference = FieldNode(
        path="user_id", name="user_id", kind=FieldKind.SCALAR,
        types=[TypeObservation(bson_type="objectId", count=3, rate=1.0)],
        sample_size=3, presence_rate=1.0, null_rate=0.0, absent_rate=0.0,
        declared=DeclaredConstraints(required=True, bson_types=["objectId"]),
        ref_target=RefCandidate(collection="users", match_rate=1.0, method="lookup", sampled=3, found=3),
    )
    object_id = IdProfile(types=[TypeObservation(bson_type="objectId", count=3, rate=1.0)], sample_size=3)
    ir = DocumentIR(collections=[
        Collection(name="orders", fields=[reference], id_profile=object_id),
        Collection(name="users", id_profile=object_id),
    ])

    artifacts = RelationalEmitter(dialect="postgresql").emit(ir, propose_reverse(ir))

    assert '"user_id" BIGINT NULL' in artifacts.pre_load_sql
    assert 'FOREIGN KEY ("user_id")' in artifacts.post_load_sql


def test_numeric_validator_bound_is_not_emitted_for_text_target_column() -> None:
    version = FieldNode(
        path="version", name="version", kind=FieldKind.SCALAR,
        types=[TypeObservation(bson_type="string", count=5, rate=1.0)],
        sample_size=5, presence_rate=1.0, null_rate=0.0, absent_rate=0.0,
        declared=DeclaredConstraints(minimum=1.0),
    )
    ir = DocumentIR(collections=[Collection(
        name="order_tags", fields=[version],
        id_profile=IdProfile(types=[TypeObservation(bson_type="objectId", count=5, rate=1.0)], sample_size=5),
    )])

    artifacts = RelationalEmitter(dialect="postgresql").emit(ir, propose_reverse(ir))

    assert 'CHECK ("version" >= 1.0)' not in artifacts.pre_load_sql
    assert '"version" >= 1.0' not in artifacts.post_load_sql
    assert any("non-numeric SQL type" in item["reason"] for item in artifacts.not_translated)
